let favoriteIndexNames=['上证指数','深证成指','创业板指','科创 50','北证 50','中证全指'];
let activeIndexGroup='全部',indexQuery='';
function indexSpark(item){const values=[];let value=30;for(let i=0;i<14;i++){value+=((i*item.seed)%7-3)*.8+(item.change>=0?1.1:-1.1);values.push(value.toFixed(1))}return values.join(',')}
function signed(value){return`${value>=0?'+':'−'}${Math.abs(value).toFixed(2)}%`}
function favoriteCard(item){return`<article class="index-card${item.name==='上证指数'?' selected':''}" data-symbol="${item.name}"><div class="index-head"><span>${item.name}<small>${item.code}</small></span><span class="market-tag">${item.market}</span></div><div class="index-main"><div><strong class="index-value">${item.point}</strong><span class="change ${item.change>=0?'up':'down'}">${signed(item.change)}</span></div><div class="sparkline ${item.change>=0?'up-line':'down-line'}" data-spark="${indexSpark(item)}"></div></div><div class="index-foot"><span>成交额 <b>${item.amount}</b></span><span class="${item.delta>=0?'up':'down'}">较昨日 ${signed(item.delta)}</span></div></article>`}
function renderFavoriteIndices(){const grid=$('.index-grid');grid.innerHTML=favoriteIndexNames.map(name=>favoriteCard(allMarketIndices.find(item=>item.name===name))).join('');grid.style.gridTemplateColumns=`repeat(${Math.min(6,favoriteIndexNames.length)},minmax(0,1fr))`;$$('.index-card',grid).forEach(wireIndexCard);$('.section-topline .soft-badge').textContent=`核心关注 · ${favoriteIndexNames.length} / ${allMarketIndices.length}`;renderSparklines()}
function openMarketIndex(item){const card=document.createElement('article');card.className='index-card';card.dataset.symbol=item.name;card.innerHTML=favoriteCard(item).replace(/^<article[^>]*>|<\/article>$/g,'');wireIndexCard(card);card.click()}
function renderIndexDirectoryRows(){const tbody=$('.index-directory-table tbody');const scroll=$('.index-table-wrap').scrollTop;tbody.innerHTML=allMarketIndices.map(item=>`<tr data-index-name="${item.name}" data-index-group="${item.group}"><td><div class="index-name"><button class="favorite-index${favoriteIndexNames.includes(item.name)?' active':''}" data-favorite-index="${item.name}" title="${favoriteIndexNames.includes(item.name)?'移出核心关注':'加入核心关注'}"><i data-icon="star"></i></button><span><strong>${item.name}</strong><small>${item.code} · ${item.market}</small></span></div></td><td><span class="group-label">${item.group}</span></td><td class="num strong">${item.point}</td><td class="num strong ${item.change>=0?'up':'down'}">${signed(item.change)}</td><td><div class="sparkline ${item.change>=0?'up-line':'down-line'}" data-spark="${indexSpark(item)}"></div></td><td class="num">${item.amount}</td><td class="num ${item.delta>=0?'up':'down'}">${signed(item.delta)}</td><td><span class="market-state ${item.group==='美股'?'':'open'}">${item.group==='美股'?'已收盘':'交易中'}</span></td></tr>`).join('');hydrateIcons(tbody);$$('tr[data-index-name]',tbody).forEach(row=>row.addEventListener('click',()=>openMarketIndex(allMarketIndices.find(item=>item.name===row.dataset.indexName))));$$('[data-favorite-index]',tbody).forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();const name=btn.dataset.favoriteIndex;if(favoriteIndexNames.includes(name))favoriteIndexNames=favoriteIndexNames.filter(item=>item!==name);else{if(favoriteIndexNames.length>=6){toast('核心关注最多显示 6 个，请先移除一个');return}favoriteIndexNames.push(name)}favoriteIndexNames=allMarketIndices.filter(item=>favoriteIndexNames.includes(item.name)).map(item=>item.name);renderFavoriteIndices();renderIndexDirectoryRows();toast(`${name}已${btn.classList.contains('active')?'移出':'加入'}核心关注`)}));$('.index-table-wrap').scrollTop=scroll;applyIndexFilters();renderSparklines()}
function applyIndexFilters(){let visible=0;$$('.index-directory-table tbody tr[data-index-name]').forEach(row=>{const item=allMarketIndices.find(entry=>entry.name===row.dataset.indexName),groupMatch=activeIndexGroup==='全部'||item.group===activeIndexGroup,queryMatch=!indexQuery||`${item.name}${item.code}`.toLowerCase().includes(indexQuery);row.hidden=!(groupMatch&&queryMatch);if(!row.hidden)visible++});$('.index-directory-title>span').textContent=`显示 ${visible} 个指数 · 点击一行查看 K 线`;$('.index-directory-empty')?.remove();if(!visible){const empty=document.createElement('div');empty.className='index-directory-empty';empty.textContent='没有找到匹配的指数';$('.index-table-wrap').appendChild(empty)}}
function buildIndexDirectory(){const oldPreview=$('.watch-preview');if(!oldPreview)return;const directory=document.createElement('section');directory.className='panel index-directory';directory.innerHTML=`<div class="index-directory-head"><div class="index-directory-title"><h2>指数全景</h2><span>22 个指数 · 点击一行查看 K 线</span></div><div class="index-directory-actions"><label class="index-filter-search"><i data-icon="search"></i><input placeholder="搜索指数名称或代码" aria-label="搜索指数"/></label></div></div><div class="index-group-tabs">${[['全部',22],['A股核心',5],['A股规模',4],['全A口径',3],['A股主题',2],['港股',3],['美股',5]].map(([name,count],i)=>`<button class="${i===0?'active':''}" data-index-group-filter="${name}">${name}<span>${count}</span></button>`).join('')}</div><div class="index-table-wrap"><table class="data-table index-directory-table"><thead><tr><th>指数</th><th>分组</th><th class="num" data-index-sort="point">最新点位</th><th class="num" data-index-sort="change">涨跌幅</th><th>当日走势</th><th class="num" data-index-sort="amount">成交额</th><th class="num" data-index-sort="delta">较昨日</th><th>交易状态</th></tr></thead><tbody></tbody></table></div>`;oldPreview.replaceWith(directory);hydrateIcons(directory);$$('[data-index-group-filter]',directory).forEach(btn=>btn.addEventListener('click',()=>{activeIndexGroup=btn.dataset.indexGroupFilter;$$('[data-index-group-filter]',directory).forEach(el=>el.classList.toggle('active',el===btn));applyIndexFilters()}));$('.index-filter-search input',directory).addEventListener('input',e=>{indexQuery=e.target.value.trim().toLowerCase();applyIndexFilters()});$$('[data-index-sort]',directory).forEach((th,index)=>{th.classList.add('sortable');th.addEventListener('click',()=>{const keys=['point','change','amount','delta'],key=keys[index],asc=!th.classList.contains('sort-asc');$$('[data-index-sort]',directory).forEach(el=>el.classList.remove('sort-asc','sort-desc'));th.classList.add(asc?'sort-asc':'sort-desc');const rows=$$('.index-directory-table tbody tr[data-index-name]');rows.sort((a,b)=>{const av=cellNumber(allMarketIndices.find(item=>item.name===a.dataset.indexName)[key].toString()),bv=cellNumber(allMarketIndices.find(item=>item.name===b.dataset.indexName)[key].toString());return asc?av-bv:bv-av});const tbody=$('.index-directory-table tbody');rows.forEach(row=>tbody.appendChild(row))})});renderIndexDirectoryRows()}
function openIndexManager(){const modal=enhancedDialog('full-index-manager','管理核心关注指数',`<div class="index-manager-grid">${allMarketIndices.map(item=>`<label class="index-option"><input type="checkbox" data-index-favorite-option="${item.name}" ${favoriteIndexNames.includes(item.name)?'checked':''}/><span>${item.name}<small>${item.code}</small></span><span class="group-label">${item.group}</span></label>`).join('')}</div><div class="index-manager-note"><span>首页顶部最多显示 6 个；全部 22 个始终保留在指数全景中。</span><span>已选 <b id="index-selected-count">${favoriteIndexNames.length}</b> / 6</span></div>`,{wide:true,subtitle:'调整首页顶部的常用指数，不会删除完整指数清单。',actions:'<button class="button ghost" id="reset-index-favorites">恢复默认</button><button class="button primary" id="save-index-favorites">保存关注</button>'});$$('[data-index-favorite-option]',modal).forEach(input=>input.addEventListener('change',()=>{$('#index-selected-count',modal).textContent=$$('[data-index-favorite-option]:checked',modal).length}));$('#reset-index-favorites',modal).addEventListener('click',()=>{const defaults=['上证指数','深证成指','创业板指','科创 50','北证 50','中证全指'];$$('[data-index-favorite-option]',modal).forEach(input=>input.checked=defaults.includes(input.dataset.indexFavoriteOption));$('#index-selected-count',modal).textContent='6'});$('#save-index-favorites',modal).addEventListener('click',()=>{const selected=$$('[data-index-favorite-option]:checked',modal).map(input=>input.dataset.indexFavoriteOption);if(selected.length>6){toast('最多选择 6 个核心关注指数');return}if(!selected.length){toast('请至少保留 1 个核心关注指数');return}favoriteIndexNames=allMarketIndices.filter(item=>selected.includes(item.name)).map(item=>item.name);renderFavoriteIndices();renderIndexDirectoryRows();closeEnhancedDialog('full-index-manager');toast('核心关注指数已更新')})}
buildIndexDirectory();renderFavoriteIndices();
rebind($$('.section-topline .text-button').find(btn=>btn.textContent.includes('管理指数')),openIndexManager);
